 g.fillStyle=col;g.fillRect(x-h*.16,y-h+2*r+2,h*.32,h*.42);g.strokeStyle='#78350f';g.lineWidth=Math.max(2,u*.07);g.beginPath();g.moveTo(x-h*.09,y-h*.26);g.lineTo(x-h*.09,y);g.moveTo(x+h*.09,y-h*.26);g.lineTo(x+h*.09,y);
