const SAYS=[{t:'The answer is 9.',z:1},{t:'What could you try?',z:0},{t:'Here, I will do it for you.',z:1},{t:'Look at the first sound.',z:0},{t:'Just copy mine.',z:1},{t:'Try counting on from 7.',z:0}];
