  c.beginPath();c.moveTo(x,y);c.lineTo(x+w,y);c.lineTo(x+w,y+h*.75);c.quadraticCurveTo(x+w,y+h,x+w*.75,y+h);c.lineTo(x+w*.25,y+h);c.quadraticCurveTo(x,y+h,x,y+h*.75);c.closePath();
