const COL=[{k:'R',n:'red',c:'#dc2626'},{k:'B',n:'blue',c:'#2563eb'}];
const WITH=['3/5','2/5','3/5','2/5','3/5','2/5'],WITHOUT=['3/5','2/5','2/4','2/4','3/4','1/4'];
