/* Data for the subtracting-multiples-of-10 lab (flag_subten.js; bundled in learn.js so the lab file stays small).
   Each sum is a multiple of 10 minus a multiple of 10 with a positive difference (CCSS 1.NBT.C.6, range 10–90). */
const SUBTENART=(()=>{
const TAKE=[[70,30],[80,50],[60,20]];
const LEAVE=[[80,30],[50,20],[90,40]];
const FACTS=[[90,40,[['9 − 4 = 5','ok'],['9 + 4 = 13','add'],['90 − 4 = 86','ones']]],[80,30,[['8 + 3 = 11','add'],['8 − 3 = 5','ok'],['80 − 3 = 77','ones']]],[60,40,[['60 − 4 = 56','ones'],['6 + 4 = 10','add'],['6 − 4 = 2','ok']]]];
const HOPS=[[90,60],[70,40],[100,30]];
const KIDS=[[[70,30],[['Ali',4,'Ali worked out 7 − 3 = 4 but forgot these are tens. 4 tens is 40.'],['Bea',40,''],['Cal',100,'Cal added 70 + 30. Taking away makes the number smaller.']]],
 [[60,20],[['Dev',80,'Dev added 60 + 20 instead of taking away.'],['Eli',50,'Eli took away only one ten. 20 is 2 tens, so take away 2 bundles.'],['Fay',40,'']]],
 [[90,50],[['Gus',40,''],['Hana',4,'Hana wrote the ones fact 9 − 5 = 4. It is 4 tens: 40.'],['Ivy',85,'Ivy took away 5 ones, not 5 tens. 50 is five tens.']]]];
const QZ=[['80 − 40 = ?','40',[['4','tensdrop'],['120','added']]],
 ['50 − 30 = ?','20',[['2','tensdrop'],['47','onesonly']]],
 ['9 − 6 = 3. So 90 − 60 = ?','30',[['3','tensdrop'],['150','added']]],
 ['70 − ? = 20','50',[['5','tensdrop'],['90','added']]],
 ['How many jumps of 10 back for 100 − 40?','4',[['40','jumps'],['6','jumpsleft']]],
 ['Which fact helps with 60 − 20?','6 − 2 = 4',[['6 + 2 = 8','addfact'],['60 − 2 = 58','onesonly']]]];
const WHY={tensdrop:'That is the ones fact. You took away tens, so the answer is tens: put the 0 back.',added:'That is adding. Taking away makes the number smaller.',onesonly:'Take away tens, not ones. 30 is 3 tens.',
 jumps:'Each jump is one ten. 40 is 4 tens, so 4 jumps.',jumpsleft:'6 jumps would land on 40. You jump back 4 tens and land on 60.',addfact:'You need a take-away fact. 6 tens − 2 tens = 4 tens.'};
return{TAKE,LEAVE,FACTS,HOPS,KIDS,QZ,WHY}})();
/* Why Next? visual cues for progress: per-topic progress rings and a subtle mastery celebration (skipped under reduced motion). */
const LEARN_FX=(()=>{
function progress(id){if(LEARN.mastered(id)||LEARN.known(id))return 1;const les=LEARN.L[id];if(!les)return 0;const pr=LEARN.prog(id);
 const p=Object.keys(pr.practice||{}).length/(les.practice?les.practice.length:les.np||1),m=(pr.best||0)/(les.mastery?les.mastery.draw:les.md||1);return Math.min(.95,p*.5+m*.5)}
function ring(id,size=18){const v=progress(id),r=size/2-2.5,C=2*Math.PI*r,pc=Math.round(v*100);
 return `<svg class="pring" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img" aria-label="Progress ${pc}%"><title>Progress ${pc}%</title><circle cx="${size/2}" cy="${size/2}" r="${r}" class="pr-bg"/><circle cx="${size/2}" cy="${size/2}" r="${r}" class="pr-fg${v>=1?' done':''}" stroke-dasharray="${(C*v).toFixed(2)} ${C.toFixed(2)}" transform="rotate(-90 ${size/2} ${size/2})"/></svg>`}
function sync(id){const h=document.querySelector('.lhead svg.pring');if(h)h.outerHTML=ring(id,24);
 for(const b of document.querySelectorAll(`.item[data-id="${CSS.escape(id)}"] .lbs`)){const a=b.querySelector('.age');b.innerHTML=(a?a.outerHTML:'')+LEARN.badge(id)}}
function celebrate(host){if(!host)return;host.classList.add('fx-win');if(VIS.reduced())return;const b=document.createElement('span');b.className='fx-burst';b.setAttribute('aria-hidden','true');
 for(let i=0;i<12;i++){const d=document.createElement('i');d.style.setProperty('--a',i*30+'deg');b.appendChild(d)}host.prepend(b);setTimeout(()=>b.remove(),1400)}
return{sync,progress,ring,celebrate}})();
/* Reel UI shared by the learn panel: picking, mirrors, slots and the player. Split out of learn_panel.js (size limit). */
/* Reel slot: a short vertical explainer per flagship topic, lazy (poster only until tapped), captions on, never autoplays. */
/* Reel catalogue: learn/reels/manifest.json maps topic id -> list of reels. Each visit shows one reel the learner has not seen yet
   (random among unseen, remembered in localStorage "wn_reels_seen"); once all are seen the rotation starts again. */
/* Seen-reel memory: {topicId:[file,...]}. Any other shape (null, array, string, junk entries) is treated as empty so the picker never throws; see docs/STATECHART.md and verify/. */
const reelSeen=()=>{let s;try{s=JSON.parse(localStorage.getItem('wn_reels_seen')||'{}')}catch(e){s=null}if(!s||typeof s!=='object'||Array.isArray(s))return{};for(const k in s)if(!Array.isArray(s[k]))delete s[k];else s[k]=s[k].filter(x=>typeof x==='string');return s},reelMark=(tid,f)=>{try{const s=reelSeen(),l=s[tid]||[];if(!l.includes(f))l.push(f);s[tid]=l;localStorage.setItem('wn_reels_seen',JSON.stringify(s))}catch(e){}};
const reelPick=(tid,R,skip)=>{const seen=reelSeen()[tid]||[];let pool=R.filter(r=>!seen.includes(r.f)&&r.f!==skip);if(!pool.length){try{const s=reelSeen();s[tid]=[];localStorage.setItem('wn_reels_seen',JSON.stringify(s))}catch(e){}pool=R.filter(r=>r.f!==skip);if(!pool.length)pool=R}return pool[Math.floor(Math.random()*pool.length)]};
/* Mirrors for a CDN reel file: jsDelivr's main host, its Fastly host, then GitHub raw (all send CORS *). A same-origin or
   other URL has no mirrors. Videos and posters step to the next mirror on error, so one blocked host does not hide reels. */
/* Reel hosts in order: the self-hosted copy (WN_RHOST, Supabase Storage), then jsDelivr, its fastly edge and raw GitHub (T5). */
const jsdChain=u=>{const m=/^https:\/\/cdn\.jsdelivr\.net\/gh\/([^/@]+)\/([^/@]+)@([0-9a-f]+)\/(.+)$/.exec(u);return m?[u,`https://fastly.jsdelivr.net/gh/${m[1]}/${m[2]}@${m[3]}/${m[4]}`,`https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}/${m[4]}`]:[u]};
const reelMirrors=(u,alt)=>alt&&alt!==u?[u,...jsdChain(alt)]:jsdChain(u);
window.WN_reelImgErr=img=>{const l=reelMirrors(img.dataset.src0||(img.dataset.src0=img.src),img.dataset.alt&&img.dataset.alt+'.jpg'),k=(+img.dataset.mi||0)+1;if(k<l.length){img.dataset.mi=k;img.src=l[k]}else img.onerror=null};
const reelFig=(tid,R,r,from)=>{const A=(r.x&&(window.WN_RPARTS||{})[r.x])||(window.WN_BASE||'')+'reels/',B=window.WN_RHOST||A,i=R.indexOf(r);return `<figure class="reel" data-tid="${tid}" data-f="${r.f}"><button type="button" class="reel-play" data-reel="${B}${r.f}" data-alt="${A}${r.f}" aria-label="Play video: ${r.t} (${r.d} seconds, with captions)"><img src="${B}${r.f}.jpg" data-alt="${A}${r.f}" onerror="WN_reelImgErr(this)" alt="" loading="lazy" decoding="async" fetchpriority="low" width="180" height="320"><span class="reel-ico" aria-hidden="true">▶</span><span class="reel-d">${r.d}s</span></button><figcaption>${from?`<span class="reel-from">From <button type="button" class="linkish" data-go="${tid}">${esc(N.get(tid).n)}</button></span><br>`:''}${r.t}${r.review?' <span class="reel-rev">· science check pending</span>':''}${R.length>1&&!from?`<br><span class="reel-n">${i+1} of ${R.length}</span> <button type="button" class="linkish reel-next">Another reel ↻</button>`:''}</figcaption></figure>`};
window.wnIdle=window.wnIdle||(()=>window.WN_IDLE||(window.WN_IDLE=new Promise(ok=>{const go=()=>(window.requestIdleCallback||setTimeout)(()=>ok(),{timeout:1200});document.readyState==='complete'?go():addEventListener('load',go,{once:true})})));
let reelLd=null;const reelLoad=()=>reelLd||(reelLd=window.wnIdle().then(()=>new Promise((ok,no)=>{const s=document.createElement('script');s.src=(window.WN_BASE||'')+'wn/'+window.WN_REELS_LAZY.u;s.onload=ok;s.onerror=()=>{reelLd=null;no()};document.head.appendChild(s)})));
